For a finite set $\X$, we denote the \emph{free vector space} over $\X$ by $\R^\X = \{ \mu\colon \X \to \R \}$. 
Its elements can be identified with vectors $(\mu_x)_{x\in\X}$. 
Similarly, we denote the vectors with non-negative entries and positive entries by $\R_{\ge0}^\X$ and $\R_{>0}^\X$, respectively. 
For two elements $\mu, \nu\in\R^\X$ we denote the \emph{Hadamard product}, i.e., the entrywise product, between $\mu$ and $\nu$ by $\mu\odot\nu\in\R^\X$, so that $\mu\odot\nu(x) \coloneqq \mu(x)\nu(x)$.
The \emph{total variation} norm $\lVert \cdot \rVert_{\TV}\colon\R^\X\to\R$ is given by $\lVert \mu \rVert_{\TV} \coloneqq \frac12\sum_{x}\lvert \mu_x \rvert$. 
Finally, with $\mathds{1}_\X\in\R^\X$ we denote the all-one vector. 

A \emph{polyhedron} is a set $P = \{ \mu\in\R^\X : \ell_i(\mu) \ge 0 \text{ for } i=1, \dots, k \}\subseteq \R^\X$, where $\ell_i\colon\R^\X\to\R$ are affine linear functions for $i=1, \dots, k$. 
A bounded (and thus compact) polyhedron is called a \emph{polytope}. 
A polytope can be shown to be the convex hull of finitely many extreme points, which are called \emph{vertices} and which we denote by $\operatorname{Vert}(P)$. 
Two vertices $\mu_1, \mu_2\in\operatorname{Vert}(P)$ are called \emph{neighbors} if the subspace $\{ c\in\R^\X : c^\top \mu_1 = c^\top \mu_2 = \max_{\mu\in P} c^\top \mu \}$ has dimension $\lvert \X \rvert-1$. 
We denote the set of all neighbors of a vertex $\mu$ by $N(\mu) \subseteq\operatorname{Vert}(P)$.  
The \emph{affine space} $\operatorname{aff\,span}(P)$ of a polytope $P\subseteq\R^\X$ is the smallest affine subspace of $\R^\X$ containing $P$. 
The relative interior $\operatorname{int}(P)$ and boundary $\partial P$ of $P$ are the interior and boundary of $P$ in its affine hull. 
Finally, the \emph{tangent space} $TP$ of $P$ is given by the linear part of $\operatorname{aff\,span}(P)$. 

We call $\Delta_\X \coloneqq \left\{ \mu\in\R^\X_{\ge0} : \sum_{x} \mu_x=1 \right\}$ the \emph{probability simplex}. 
We say that $\mu\in\Delta_\X$ is absolutely continuous with respect to $\nu\in\Delta_\X$ if $\nu(x) = 0$ implies $\mu(x)=0$ and write $\mu \ll \nu$. 


The \emph{Fisher-Rao metric} is a Riemannian metric on the positive orthant given by 
\begin{equation}
    g_{\mu}^{\FR}(v,w) \coloneqq \sum_{x\in \X} \frac{v_x w_x}{\mu_x} \quad \text{for all } v, w\in\R^{\X}, \mu\in\R^{\X}_{>0},
\end{equation}
where we denote the induced norm by $\lVert v \rVert_{g_\mu^{\FR}} \coloneqq {g_{\mu}^{\FR}(v,v)}^{\frac12}$. 


The Fisher-Rao metric is closely connected to the negative {Shannon entropy} 
\begin{equation}
    \phi(\mu) = -H(\mu) \coloneqq \sum_{x\in\X} \mu_x \log \mu_x  \quad \text{for all } \mu\in\R^{\X}_{>0}
\end{equation}
as it is induced by the Hessian of the (negative) entropy, meaning that we have $g_{\mu}^{\FR}(v,w) = v^\top \nabla^2 \phi(\mu) w$ for all $v, w\in\R^{\X}, \mu\in\R^{\X}_{>0}$. 
As such, the Fisher-Rao metric falls into the class of \emph{Hessian metrics} that have been studied in convex optimization; we refer to~\cite{alvarez2004hessian, mueller2023thesis} for general well-posedness and convergence results. 
An important concept in the analysis of Hessian gradient flows is the \emph{Bregman divergence} induced by $\phi$, which in the case of the negative entropy is given by the \emph{KL-divergence} 
\begin{equation}
    \KL (\mu, \nu) \coloneqq  \phi(\mu) - \phi(\nu) - \nabla \phi(\nu)(\mu-\nu) = \sum_{x\in \X} \mu_x \log \frac{\mu_x}{\nu_x} - \sum_{x\in \X} \mu_x + \sum_{x\in \X} \nu_x 
\end{equation}
for $\mu, \nu\in\R_{\ge0}^\X$ with $\mu\ll\nu$, where we use the common convention $0\log\frac00\coloneqq0$. 

Consider now a continuously differentiable function $f\colon\R_{\ge0}^\X\to\R$ that we assume to be differentiable on $\R_{>0}^\X$ that we want to optimize over a polytope $P= \R_{\ge0}^{\X}\cap\mathcal L$, where $\mathcal L$ is a linear space. 
We denote the gradient of $f\colon \R_{>0}^\X\to\R$ at $\mu\in\R_{>0}^\X$ with respect to the Fisher-Rao metric by $\nabla^{\FR}f(\mu)$ and call it the \emph{Fisher-Rao gradient}. 
Further, we denote the Fisher-Rao gradient of $f\colon\operatorname{int}(P)\to\R$ by $\nabla^{\FR}_P f(\mu)\in TP$, which is uniquely determined by 
\begin{equation}
    g_\mu^{\FR}(\nabla^{\FR}_P f(\mu),v) = df(\mu)v \quad \text{for all } v\in TP.
\end{equation}
Note that $\nabla^{\FR}_P f(\mu)$ is the projection of $\nabla^{\FR}f(\mu)$ with respect to the Fisher-Rao metric onto $TP$.
By examining the definition of the Fisher-Rao metric we see that this is equivalent to 
\begin{equation}
\label{eq:characterizationFRGradient}
    \langle \nabla^2\phi(\mu)\nabla^{\FR}_P  f(\mu), v \rangle = \langle \nabla f(\mu), v \rangle \quad \text{for all } v\in TP. 
\end{equation}

We say that $(\mu_t)_{t\in [0, T)} \subseteq \operatorname{int}(P)$ solves the \emph{Fisher-Rao gradient flow} if it solves the gradient flow with respect to the Fisher-Rao metric, i.e., if 
\begin{equation}\label{eq:FRGF}
    \partial_t \mu_t = \nabla^{\FR}_P  f(\mu_t) \quad \text{for all } t\in[0, T). 
\end{equation}
By using the characterization~\eqref{eq:characterizationFRGradient} of $\nabla^{\FR}_P f(\mu_t)$, we see that $(\mu_t)_{t\in [0, T)} \subseteq \operatorname{int}(P)$ solves the Fisher-Rao gradient flow~\eqref{eq:FRGF}
if and only if we have 
\begin{equation}\label{eq:explicitFRGF}
    \langle \nabla^2 \phi(\mu_t) \partial_t \mu_t, v \rangle = \langle \nabla f(\mu_t), v \rangle 
    \quad \text{for all } v\in TP, t\in[0, T). 
\end{equation}


In the remainder, we study linear programs and work in the following setting. 

\begin{setting}\label{setting:generalLP}
We consider a finite set $\X$ and a linear program 
    \begin{equation}\label{eq:LP}
        \max c^\top \mu \quad \text{subject to } \mu\in P, 
    \end{equation}
with cost $c\in\R^{\X}$ and feasible region $P = \R^\X_{\ge0} \cap  \mathcal L$ with $P \cap \R^\X_{>0}\ne\emptyset$, where $\mathcal L\subseteq\R^{\X}$ is an affine space. 
By $(\mu_t)_{t\in[0, T)}\subseteq\operatorname{int}(P)$ we denote a solution of the Fisher-Rao gradient flow~\eqref{eq:FRGF} with initial condition $\mu_0\in P \cap \R_{>0}^\X$ and potential $f(\mu) = c^\top \mu$, where $T\in\R_{\ge0}\cup\{+\infty\}$. 
\end{setting}


\section{Convergence of Fisher-Rao Gradient Flows}\label{sec:linearConvergeFRGF}
We have seen that Fisher-Rao gradient flows converge globally at a sublinear rate $O(t^{-1})$. 
We now build on this analysis and show that once the gradient flow enters a vicinity of the optimizer, it converges at a quasi-linear rate $O(t^\kappa e^{-\Delta t})$, where $\Delta>0$ depends on the geometry of the linear program and $\kappa>0$ depends on the initial condition $\mu_0$. 
Note that this yields $O(e^{-c t})$ convergence for all $c<\Delta$ and hence we also simply talk of a linear convergence rate.
We consider linear programs of the following form. 
\begin{setting}\label{setting:LP-inside-Simplex}
We consider a finite set $\X$ and a linear program 
    \begin{equation}\label{eq:LP-inside-simplex}
        \max c^\top \mu \quad \text{subject to } \mu\in P, 
    \end{equation}
with cost $c\in\R^{\X}$ and feasible region $P = \Delta_\X \cap  \mathcal L$ with $P \cap \R^\X_{>0}\ne\emptyset$, where $\mathcal L\subseteq\R^{\X}$ is an affine space. 
By $(\mu_t)_{t\ge0}\subseteq\operatorname{int}(P)$ we denote the solution of the Fisher-Rao gradient flow~\eqref{eq:FRGF} with initial condition $\mu_0\in P \cap \R_{>0}^\X$ and the potential $f(\mu) = c^\top \mu$. 
\end{setting}

