statement.raw_tex:
\begin{restatable}[Linear convergence of Fisher-Rao GFs of LPs]{theorem}{convergenceFRGF}
\label{thm:convergenceFRGF}
Consider Setting~\ref{setting:LP-inside-Simplex} and assume that the linear program~\eqref{eq:LP-inside-simplex} admits a unique solution $\mu^\star\in P$. 
Let 
\begin{align}\label{eq:Delta}
    \Delta \coloneqq \min \left\{ \frac{c^\top \mu^\star - 
    c^\top \mu}{\lVert \mu^\star - \mu \rVert_{\TV }} : \mu\in N(\mu^\star)  \right\},
\end{align}
where $N(\mu^\star)$ denotes the set of neighboring vertices of $\mu^\star$ and set 
\begin{equation}\label{eq:definitiont_0}
    t_0 \coloneqq \frac{2 \KL (\mu^\star, \mu_0)}{\Delta \cdot \min\{ \mu^\star_x : \mu^\star_x>0 \}} . 
\end{equation}
Then for any $t\ge t_0$ we have 
\begin{align}\label{eq:linearConvergenceKL}
    \KL (\mu^\star, \mu_t) \le \KL (\mu^\star, \mu_0) \exp\left( -\Delta(t-t_0) +  2 t_0 \Delta 
    \log\left(\frac{t+t_0}{2t_0}\right) \right), 
\end{align}
as well as 
\begin{align}\label{eq:linearConvergenceValue}
    c^\top \mu^\star - c^\top \mu_t \le \Delta \KL (\mu^\star, \mu_0) \exp\left( -\Delta(t-t_0) +  2 t_0 \Delta \log\left(\frac{t+t_0}{2t_0}\right) \right). 
\end{align}
\end{restatable}

