proof.raw_tex:
\begin{proposition}[Central path property,\cite{alvarez2004hessian}]
    Consider Setting~\ref{setting:generalLP}. 
    Then $\mu_t$ is uniquely characterized by 
    \begin{equation}\label{eq:centralPath}
        \mu_t = \argmax\left\{ c^\top \mu - t^{-1} \KL (\mu, \mu_0) : \mu \in P \right\} \quad \text{for all } t\in(0,T). 
    \end{equation}
\end{proposition}

\begin{proof}
    Let $\hat{\mu}_t\in P$ denote the unique maximizer of $g(\mu)\coloneqq c^\top\mu - t^{-1} \KL (\mu, \mu_0)$ over $P$ for $t>0$, then surely $\hat{\mu}_t\in \operatorname{int}(P)$. 
    Thus, $\hat{\mu}_t$ is uniquely determined by $\langle \nabla g(\hat{\mu}_t), v\rangle = 0$ for all $v\in TP$. 
    Direct computation yields $\nabla g({\mu}) = c - t^{-1} (\nabla\phi(\mu) - \nabla\phi(\mu_0))$ and hence $\hat{\mu}_t$ is uniquely determined by 
    \begin{equation*}
        t\langle c, v\rangle = \langle \nabla\phi(\hat{\mu}_t) - \nabla\phi(\mu_0), v\rangle \quad \text{for all } v\in TP. 
    \end{equation*} 
    On the other hand, for the gradient flow, we can use~\eqref{eq:explicitFRGF} and compute for $v\in TP$ 
    \begin{align*}
        \langle \nabla\phi(\mu_t) - \nabla\phi(\mu_0), v \rangle & = \int_{0}^t \partial_s \langle \nabla \phi(\mu_s), v \rangle \D s 
        = \int_{0}^t \langle \nabla^2 \phi(\mu_s)\partial_s \mu_s, v \rangle \D s 
        \\ & = \int_{0}^t \langle \nabla f(\mu_s) \mu_s, v \rangle \D s 
        = \int_{0}^t \langle c, v \rangle \D s = t \langle c, v \rangle . 
    \end{align*}
    This shows $\mu_t = \hat{\mu}_t$ as claimed. 
\end{proof}

\begin{corollary}[Sublinear convergence rate,\cite{alvarez2004hessian}]\label{prop:sublinearRate}
    Consider Setting~\ref{setting:generalLP} and assume that the linear program~\eqref{eq:LP} admits a solution $\mu^\star\in P$. 
    Then for $\mu\in P$ it holds that 
\begin{equation}\label{eq:sublinearConvergence}
        c^\top \mu^\star - c^\top\mu_t \le \frac{\KL (\mu^\star, \mu) - \KL (\mu_t, \mu)}t \le \frac{\KL (\mu^\star, \mu_0)}t \quad \text{for all } t\in[0, T). 
    \end{equation}
\end{corollary}

\begin{proof}
    We have $c^\top \mu_t - t^{-1} \KL (\mu_t, \mu) \ge c^\top \mu^\star - t^{-1} \KL (\mu^\star, \mu)$ by the central path property.
    Rearranging yields the result. 
\end{proof}

\begin{theorem}[Well-posedness of  FR GFs,\cite{alvarez2004hessian}]
    Consider Setting~\ref{setting:generalLP}. 
    Then there exists a unique global solution $(\mu_{t})_{t\ge0}\subseteq\operatorname{int}(P)$ of the Fisher-Rao gradient flow~\eqref{eq:FRGF}. 
\end{theorem}

\begin{proof}
    The local existence and uniqueness follow from the Picard-Lindelöf theorem~\cite{teschl2024ordinary}. Hence, it suffices to show that the Fisher-Rao gradient flow does not hit the boundary $\partial P$ in finite time. 
    By the central path property, this is equivalent to the statement that the solutions of all KL-regularized problems~\eqref{eq:centralPath} lie in the interior $\operatorname{int}(P)$ of the polyhedron, which can be easily checked. 
\end{proof}

\begin{lemma}\label{prop:ratesTrajectories} 
    Consider Setting~\ref{setting:generalLP} and assume that there is an optimizer $\mu^\star\in P$ and $\kappa_t>0$ for $t>t_0\ge0$ such that
\begin{equation}\label{eq:strongConvexity}
    c^\top \mu^\star - c^\top \mu_t \ge \kappa_t \KL (\mu^\star, \mu_t) \quad \text{for all } t> t_0. 
\end{equation}
Then we have 
\begin{equation}\label{eq:lem:KLConvergence}
    \KL (\mu^\star, \mu_t) \le \KL (\mu^\star, \mu_{0}) \exp\left( -\int_{t_0}^t \kappa_s \D s \right) \quad \text{for all } t\ge t_0,
\end{equation}
as well as 
\begin{equation}\label{eq:lem:convergenceValue}
    c^\top \mu^\star - c^\top \mu_t \le \kappa_t \KL (\mu^\star, \mu_{0}) \exp\left( -\int_{t_0}^t \kappa_s \D s \right) \quad \text{for all } t\ge t_0.
\end{equation}
\end{lemma}

\begin{lemma}[\cite{alvarez2004hessian}]\label{lem:evolutionKL}
Consider Setting~\ref{setting:generalLP}, whereby we allow $f\colon\R_{>0}^\X\to\R$ to be an arbitrary differentiable function, and fix $\mu\in P$. 
Then for any $t\ge0$, it holds that 
    \begin{equation}\label{eq:derivativeu}
        \partial_t \KL (\mu, \mu_t) = \langle \nabla f(\mu_t), \mu_t-\mu\rangle. 
    \end{equation}
\end{lemma}

\begin{proof}
    Denoting the negative Shannon entropy by $\phi$, we compute 
    \begin{align*}
        \partial_t \KL (\mu, \mu_t) = - \partial_t \phi(\mu_t) - \partial_t \langle \nabla \phi(\mu_t), \mu - \mu_t \rangle = \langle \nabla^2 \phi(\mu_t)\partial_t \mu_t, \mu_t - \mu \rangle.
    \end{align*}
    Now~\eqref{eq:explicitFRGF} yields the claim. 
\end{proof}

\begin{proof}[Proof of \Cref{prop:ratesTrajectories}]
Using~\eqref{eq:derivativeu} and~\eqref{eq:strongConvexity} we find that for all $t\ge T$ it holds that 
$\partial_t \KL (\mu^\star, \mu_t) = c^\top \mu_t  - c^\top \mu^\star \le - \kappa_t \KL (\mu^\star, \mu_t)$. 
Now Gronwall's inequality yields~\eqref{eq:lem:KLConvergence}. 
By \Cref{prop:sublinearRate} we have for any $h>0$ that 
    \[ c^\top \mu^\star - c^\top \mu_t \le \frac{\KL (\mu^\star, \mu_{t-h})}{h} \le  \KL (\mu^\star, \mu_{0}) \cdot \frac{\exp\left(-\int_{t_0}^{t-h} \kappa_s \D s \right)}{h}. \] 
Taking the limit $h\to0$ yields~\eqref{eq:lem:convergenceValue}. 
\end{proof}

\begin{restatable}{lemma}{TVLPEstimateWU}
\label{lem:TV-LP-estimate-withoutUniqueness}
Consider a polytope $P \subseteq \R^{\X}$ and denote by $F^\star$ the face of maximizers of the linear function $\mu\mapsto c^\top \mu$ over $P$. 
Denote the set of neighboring vertices of a vertex $\mu$ by $N(\mu)$ and let $\lVert \cdot\rVert\colon\R^{\X}\to\R_{\ge0}$ be an arbitrary semi-norm. 
Then either $F^\star = P$ or with $\frac{c}{0}\coloneqq+\infty$ for $c>0$, we have 
\begin{equation}
    \Delta\coloneqq \min \left\{ \frac{c^\top\mu^\star - c^\top\mu }{\lVert \mu^\star - \mu \rVert} : \mu^\star \in\operatorname{vert}(F^\star), \mu\in N(\mu^\star)\setminus F^\star \right\} > 0,
\end{equation}
and further 
\begin{equation}\label{eq:gapVSNorm-2}
     c^\top \mu^\star - c^\top \mu \ge \Delta \cdot \inf_{\mu^\star\in F^\star}  \lVert \mu^\star - \mu\rVert \quad \text{for all } \mu\in P.
\end{equation}
\end{restatable}

\begin{proof}
If $F^\star \ne P$, then $c^\top \mu^\star-c^\top \mu >0$ for some vertex $\mu$, which implies $\Delta>0$. 
To simplify notation we denote the set $E\coloneqq\{\mu-\mu^\star: \mu\in N(\mu^\star) \setminus F^\star, \mu^\star\in \operatorname{vert}(F^\star)\}$ of edges such that exactly one of the two endpoints is contained in $F^\star$. 
Then, the polytope $P$ is contained in 
    \[ F^\star+C = \left\{ \mu^\star + \sum_{e\in E} \alpha_e e : \mu^\star\in F^\star, \alpha_e\ge0 \text{ for all } e\in E \right\}, \]
see \Cref{app:lem:cone} and hence we can write $\mu\in P$ as $\mu = \mu^\star + \sum_{e} \alpha_e e$ for some $\mu^\star\in F^\star$. 
Using the triangle inequality we obtain 
    \[ \Delta \lVert \mu^\star - \mu \rVert \le \Delta \sum_{e\in E}\alpha_e \lVert e \rVert \le - \sum_{e\in E} \alpha_e c^\top e = c^\top \mu^\star - c^\top\mu. \]
\end{proof}

\begin{lemma}\label{lem:KLEstimateL1}
Consider a finite set $\X$ and a probability distribution $\mu\in \Delta_\X$. Let $c>1$ and set $\delta\coloneqq \frac{c-1}{c+1} 
    \cdot \min\{ \mu_x : \mu_x>0 \}>0$. 
Then for all $\nu\in\Delta_\X$ satisfying $\lVert \mu-\nu\rVert_\infty\le\delta$ it holds that 
\begin{equation}\label{eq:KLvsL1}
    \KL (\mu, \nu) \le c \cdot \lVert \mu - \nu \rVert_{\TV }. 
\end{equation}
\end{lemma}

\begin{proof}
We bound the individual summands in the KL-divergence
    \[ \KL (\mu, \nu) = \sum_{x\in\X} \mu_x \log\left( \frac{\mu_x}{\nu_x}\right) = \sum_{x\in X} \mu_x \log\left( \frac{\mu_x}{\nu_x}\right), \]
where $X\coloneqq\{x\in\X : \mu_x>0\}$. 
If $\mu_x,\nu_x>0$ then 
\begin{align}\label{eq:klIndividual}
    \begin{split}
        \mu_x \log \left(\frac{\mu_x}{\nu_x}\right) & = \mu_x \left( \log(\nu_x+(\mu_x-\nu_x)) - \log(\nu_x) \right) \\
        & \le \mu_x \left( \log(\nu_x) + \frac{\mu_x-\nu_x}{\nu_x} - \log(\nu_x) \right) 
         = (\mu_x - \nu_x)\cdot\frac{\mu_x}{\nu_x},
    \end{split}
\end{align}
where we used the convexity $\log(t+h) \le \log(t) + h/t$ for $t>0, t+h>0$. 
We set $\varepsilon\coloneqq\frac{c-1}{2}\in(0,1)$, such that 
\[ \delta = \frac{\varepsilon}{1+\varepsilon}  
    \cdot \min\big\{ \mu_x : \mu_x>0 \big\}. 
    \]
If $\lVert \mu-\nu\rVert_\infty\le\delta$ then 
    \[ \nu_x \ge \mu_x - \delta \ge \mu_x \left(1-\frac{\varepsilon}{1+\varepsilon}\right) = \frac{\mu_x}{1+\varepsilon} \]
as well as
    \[ \nu_x \le \mu_x + \delta  \le \mu_x \left(1 + \frac{\varepsilon}{1+\varepsilon}\right) \le \mu_x \left(1 + \frac{\varepsilon}{1-\varepsilon}\right) = \frac{\mu_x}{1-\varepsilon} \]
and therefore $1-\varepsilon\le \frac{\mu_x}{\nu_x}\le1+\varepsilon$. 
If $\mu_x\ge\nu_x$ then 
    \[ 
    (\mu_x-\nu_x)\cdot \frac{\mu_x}{\nu_x} 
    \le (1+\varepsilon)(\mu_x-\nu_x) 
    = \mu_x-\nu_x + \varepsilon \lvert \mu_x - \nu_x \rvert , 
    \]
and if $\mu_x<\nu_x$ then 
\begin{equation}\label{eq:almostThere}
    (\mu_x-\nu_x)\cdot \frac{\mu_x}{\nu_x} \le (1-\varepsilon)(\mu_x-\nu_x) = \mu_x-\nu_x + \varepsilon \lvert \mu_x - \nu_x \rvert. 
\end{equation}
Together with~\eqref{eq:klIndividual} summing over $x$ yields 
\begin{equation}\label{eq:there}
    \KL (\mu, \nu) \le \sum_{x\in X} (\mu_x-\nu_x) + \varepsilon \sum_{x\in X} \lvert \mu_x - \nu_x \rvert \le \sum_{x\in X} (\mu_x-\nu_x) + 2 \varepsilon \lVert \mu-\nu\rVert_{\TV } . 
\end{equation}
It remains to estimate the first part. 
Setting $X^c\coloneqq\X\setminus X$, we have 
\[ 
\sum_{x\in X} (\mu_x-\nu_x) = \sum_{x\in\X} (\mu_x-\nu_x) -  \sum_{x\in X^c} (\mu_x-\nu_x) = -  \sum_{x\in X^c} (\mu_x-\nu_x) = \sum_{x\in X^c} \lvert  \mu_x-\nu_x \rvert  
\]
since $\mu_x=0$ for $x\in X^c$. 
Now we can estimate
\begin{align}\label{eq:lastStep}
    2\sum_{x\in X} (\mu_x-\nu_x) = \sum_{x\in X} (\mu_x-\nu_x) + \sum_{x\in X^c} \lvert  \mu_x-\nu_x \rvert \le \lVert \mu-\nu\rVert_1 = 2\lVert \mu-\nu\rVert_{\TV }.
\end{align}
Combining~\eqref{eq:there} and~\eqref{eq:lastStep} yields
\[ \KL (\mu, \nu) \le (1+2\varepsilon)\lVert \mu - \nu \rVert_{\TV } = c\cdot\lVert \mu - \nu \rVert_{\TV }. \]
\end{proof}

\begin{corollary}[Local KL-TV estimate]\label{cor:TV-KL}
Consider a finite set $\X$ and a probability distribution $\mu\in \Delta_\X$. 
Then for all $\nu\in\Delta_\X$ satisfying 
\begin{equation}
    \lVert \mu - \nu \rVert_\infty < \min\{ \mu_x : \mu_x>0 \} 
\end{equation}
it holds that 
\begin{equation}\label{eq:KLvsL1-2}
    \KL (\mu, \nu) \le \frac{\min\{ \mu_x : \mu_x>0 \} +  \lVert \mu-\nu\rVert_\infty}{\min\{ \mu_x : \mu_x>0 \} - \lVert \mu-\nu\rVert_\infty} \cdot \lVert \mu - \nu \rVert_{\TV }. 
\end{equation}
\end{corollary}

\begin{proof}
    This is a direct consequence of \Cref{lem:KLEstimateL1}. 
    Indeed, for $\varepsilon>0$ small enough we have $\lVert \mu - \nu \rVert_\infty \le \frac{2-\varepsilon}{2+\varepsilon} \cdot \min\{ \mu_x : \mu_x>0 \}$ and thus by \Cref{lem:KLEstimateL1} with $c=1+\varepsilon$ we have $\KL (\mu, \nu) \le (1+\varepsilon) \lVert \mu - \nu \rVert_{\TV }$. 
    Note that $\varepsilon>0$ was arbitrary. 
\end{proof}

\begin{proof}[Proof of \Cref{thm:convergenceFRGF}]
    Setting $\delta\coloneqq \min\{ \mu_x^\star : \mu_x^\star>0 \}$ and using \Cref{lem:TV-LP-estimate-withoutUniqueness} with $\lVert\cdot\rVert_{\TV}$ and \Cref{cor:TV-KL} we have 
    \begin{equation*}
        c^\top \mu^\star - c^\top \mu_t \ge \Delta \lVert \mu^\star - \mu_t \rVert_{\TV } \ge \Delta\cdot\frac{\delta -  \lVert \mu^\star-\mu_t\rVert_\infty}{\delta + \lVert \mu^\star-\mu_t\rVert_\infty} \cdot \KL (\mu^\star, \mu_t),
    \end{equation*}
    if $\lVert \mu^\star - \mu_t \rVert_\infty < \delta$.
    By \Cref{prop:sublinearRate} we have 
    \begin{align*}
        \lVert \mu^\star - \mu_t \rVert_\infty \le 2 \lVert \mu^\star - \mu_t \rVert_{\TV } \le \frac{2c^\top(\mu^\star-\mu_t)}\Delta \le \frac{2\KL (\mu^\star,\mu_0)}{\Delta \cdot t}.
    \end{align*}
    Hence, for $t>t_0$ we have $\lVert \mu^\star - \mu_t \rVert_\infty < \delta$. 
    In this case, we can estimate 
    \begin{align*}
        \frac{\delta -  \lVert \mu^\star-\mu_t\rVert_\infty}{\delta + \lVert \mu^\star-\mu_t\rVert_\infty} & \le \frac{\delta -  2 \KL (\mu^\star, \mu_0)\Delta^{-1} t^{-1}} {\delta + 2 \KL (\mu^\star, \mu_0)\Delta^{-1} t^{-1}} 
        = \frac{t - t_0}{t + t_0} \eqqcolon \kappa_t. 
    \end{align*}
    Thus for $t>t_0$ we have $c^\top \mu^\star - c^\top \mu_t \ge \Delta \kappa_t \KL (\mu^\star, \mu_t)$, and \Cref{prop:ratesTrajectories} together with 
    \begin{equation*}
        \int_{t_0}^t \frac{s-t_0}{s+t_0} \D s = s - 2 t_0 \log(s+t_0)\Big|^{s=t}_{s=t_0} = (t-t_0) - 2 t_0 \log\left( \frac{t+t_0}{2t_0} \right)
    \end{equation*}
    yield the result. 
\end{proof}

\begin{lemma}\label{app:lem:cone}
    Consider a polytope $P\subseteq\R^\X$, a face $F\subseteq P$ and consider the cone 
    \begin{align*}
        C\coloneqq \operatorname{cone}\Big\{ \nu-\mu : \mu\in\operatorname{vert}(F), \nu\in N(\mu)\setminus F \Big\}, 
    \end{align*}
    which is generated by the edges pointing out of $F$. 
    Then we have $P\subseteq F+C$. 
\end{lemma}

\begin{proof}
This is a generalization of~\cite[Lemma 3.6]{ziegler2012lectures}, which covers the case that $F$ consists of a single vertex. 
We will show that 
\begin{align*}
    F+C \supseteq\tilde P \coloneqq \bigcap \Big\{ H\subseteq \R^\X : H \text{ is a halfspace }, P\subseteq H, H\cap F\ne\emptyset \Big\} \supseteq P, 
\end{align*}
for which we pick an element $u\in \tilde P$. 
Consider a hyperplane $H = \{\mu:a^\top \mu = \alpha\}$ separating $F$ and $\operatorname{vert}(P)\setminus F$ and consider the \emph{face figure} $P/F\coloneqq P\cap H$, which is a polytope. 
Now, we consider a translation $\tilde H = \{ \mu : a^\top\mu= \beta \}$ of $H$,  such that $u\in \tilde H$. 
Now we have 
\begin{align*}
    \tilde P = \operatorname{conv}\left\{ \mu + \frac{a^\top \mu - \beta}{a^\top \mu - a^\top \nu} \cdot (\nu-\mu) : \mu\in\operatorname{vert}(F), \nu\in N(\mu)\setminus F \right\},
\end{align*}
see~\cite[Proposition 2.30]{zieglerdiscrete}. 
Hence, we can choose convex weights $\lambda_i$ such that 
\begin{align*}
    u = \sum_{i} \lambda_i (\mu_i + \alpha_i (\nu_i-\mu_i)) =  \sum_{i} \lambda_i \mu_i + \sum_{i} \alpha_i \lambda_i (\nu_i-\mu_i) \in F + C,
\end{align*}
where $\mu_i\in\operatorname{vert}(F), \nu_i \in N(\mu_i)\setminus F$.
\end{proof}

