The \emph{Fisher-Rao metric} is a Riemannian metric on the positive orthant given by 
\begin{equation}
    g_{\mu}^{\FR}(v,w) \coloneqq \sum_{x\in \X} \frac{v_x w_x}{\mu_x} \quad \text{for all } v, w\in\R^{\X}, \mu\in\R^{\X}_{>0},
\end{equation}
where we denote the induced norm by $\lVert v \rVert_{g_\mu^{\FR}} \coloneqq {g_{\mu}^{\FR}(v,v)}^{\frac12}$.

The Fisher-Rao metric is closely connected to the negative {Shannon entropy} 
\begin{equation}
    \phi(\mu) = -H(\mu) \coloneqq \sum_{x\in\X} \mu_x \log \mu_x  \quad \text{for all } \mu\in\R^{\X}_{>0}
\end{equation}
as it is induced by the Hessian of the (negative) entropy, meaning that we have $g_{\mu}^{\FR}(v,w) = v^\top \nabla^2 \phi(\mu) w$ for all $v, w\in\R^{\X}, \mu\in\R^{\X}_{>0}$.

An important concept in the analysis of Hessian gradient flows is the \emph{Bregman divergence} induced by $\phi$, which in the case of the negative entropy is given by the \emph{KL-divergence} 
 egin{equation}
    \KL (\mu, 
u) \coloneqq  \phi(\mu) - \phi(
u) - 
abla \phi(
u)(\mu-
u) = \sum_{x\in \X} \mu_x \log  rac{\mu_x}{
u_x} - \sum_{x\in \X} \mu_x + \sum_{x\in \X} 
u_x 
\end{equation}
for $\mu, 
u\in\R_{\ge0}^\X$ with $\mu\ll
u$, where we use the common convention $0\log rac00\coloneqq0$.

By examining the definition of the Fisher-Rao metric we see that this is equivalent to 
\begin{equation}
\label{eq:characterizationFRGradient}
    \langle \nabla^2\phi(\mu)\nabla^{\FR}_P  f(\mu), v \rangle = \langle \nabla f(\mu), v \rangle \quad \text{for all } v\in TP. 
\end{equation}


We say that $(\mu_t)_{t\in [0, T)} \subseteq \operatorname{int}(P)$ solves the \emph{Fisher-Rao gradient flow} if it solves the gradient flow with respect to the Fisher-Rao metric, i.e., if 
\begin{equation}\label{eq:FRGF}
    \partial_t \mu_t = \nabla^{\FR}_P  f(\mu_t) \quad \text{for all } t\in[0, T). 
\end{equation}

By using the characterization~\eqref{eq:characterizationFRGradient} of $\nabla^{\FR}_P f(\mu_t)$, we see that $(\mu_t)_{t\in [0, T)} \subseteq \operatorname{int}(P)$ solves the Fisher-Rao gradient flow~\eqref{eq:FRGF}
if and only if we have 
\begin{equation}\label{eq:explicitFRGF}
    \langle \nabla^2 \phi(\mu_t) \partial_t \mu_t, v \rangle = \langle \nabla f(\mu_t), v \rangle 
    \quad \text{for all } v\in TP, t\in[0, T). 
\end{equation}

In the remainder, we study linear programs and work in the following setting. 

\begin{setting}\label{setting:generalLP}
We consider a finite set $\X$ and a linear program 
    \begin{equation}\label{eq:LP}
        \max c^\top \mu \quad \text{subject to } \mu\in P, 
    \end{equation}
with cost $c\in\R^{\X}$ and feasible region $P = \R^\X_{\ge0} \cap  \mathcal L$ with $P \cap \R^\X_{>0}\ne\emptyset$, where $\mathcal L\subseteq\R^{\X}$ is an affine space. 
By $(\mu_t)_{t\in[0, T)}\subseteq\operatorname{int}(P)$ we denote a solution of the Fisher-Rao gradient flow~\eqref{eq:FRGF} with initial condition $\mu_0\in P \cap \R_{>0}^\X$ and potential $f(\mu) = c^\top \mu$, where $T\in\R_{\ge0}\cup\{+\infty\}$. 
\end{setting}

\begin{setting}\label{setting:LP-inside-Simplex}
We consider a finite set $\X$ and a linear program 
    \begin{equation}\label{eq:LP-inside-simplex}
        \max c^\top \mu \quad \text{subject to } \mu\in P, 
    \end{equation}
with cost $c\in\R^{\X}$ and feasible region $P = \Delta_\X \cap  \mathcal L$ with $P \cap \R^\X_{>0}\ne\emptyset$, where $\mathcal L\subseteq\R^{\X}$ is an affine space. 
By $(\mu_t)_{t\ge0}\subseteq\operatorname{int}(P)$ we denote the solution of the Fisher-Rao gradient flow~\eqref{eq:FRGF} with initial condition $\mu_0\in P \cap \R_{>0}^\X$ and the potential $f(\mu) = c^\top \mu$. 
\end{setting}

\begin{restatable}[Linear convergence of Fisher-Rao GFs of LPs]{theorem}{convergenceFRGF}
\label{thm:convergenceFRGF}
Consider Setting~\ref{setting:LP-inside-Simplex} and assume that the linear program~\eqref{eq:LP-inside-simplex} admits a unique solution $\mu^\star\in P$. 
Let 
\begin{align}\label{eq:Delta}
    \Delta \coloneqq \min \left\{ \frac{c^\top \mu^\star - 
    c^\top \mu}{\lVert \mu^\star - \mu \rVert_{\TV }} : \mu\in N(\mu^\star)  \right\},
\end{align}
where $N(\mu^\star)$ denotes the set of neighboring vertices of $\mu^\star$ and set 
\begin{equation}\label{eq:definitiont_0}
    t_0 \coloneqq \frac{2 \KL (\mu^\star, \mu_0)}{\Delta \cdot \min\{ \mu^\star_x : \mu^\star_x>0 \}} . 
\end{equation}
Then for any $t\ge t_0$ we have 
\begin{align}\label{eq:linearConvergenceKL}
    \KL (\mu^\star, \mu_t) \le \KL (\mu^\star, \mu_0) \exp\left( -\Delta(t-t_0) +  2 t_0 \Delta 
    \log\left(\frac{t+t_0}{2t_0}\right) \right), 
\end{align}
as well as 
\begin{align}\label{eq:linearConvergenceValue}
    c^\top \mu^\star - c^\top \mu_t \le \Delta \KL (\mu^\star, \mu_0) \exp\left( -\Delta(t-t_0) +  2 t_0 \Delta \log\left(\frac{t+t_0}{2t_0}\right) \right). 
\end{align}
\end{restatable}

\begin{proposition}[Central path property,\cite{alvarez2004hessian}]
    Consider Setting~\ref{setting:generalLP}. 
    Then $\mu_t$ is uniquely characterized by 
    \begin{equation}\label{eq:centralPath}
        \mu_t = \argmax\left\{ c^\top \mu - t^{-1} \KL (\mu, \mu_0) : \mu \in P \right\} \quad \text{for all } t\in(0,T). 
    \end{equation}
\end{proposition}

\begin{proof}
    Let $\hat{\mu}_t\in P$ denote the unique maximizer of $g(\mu)\coloneqq c^\top\mu - t^{-1} \KL (\mu, \mu_0)$ over $P$ for $t>0$, then surely $\hat{\mu}_t\in \operatorname{int}(P)$. 
    Thus, $\hat{\mu}_t$ is uniquely determined by $\langle \nabla g(\hat{\mu}_t), v\rangle = 0$ for all $v\in TP$. 
    Direct computation yields $\nabla g({\mu}) = c - t^{-1} (\nabla\phi(\mu) - \nabla\phi(\mu_0))$ and hence $\hat{\mu}_t$ is uniquely determined by 
    \begin{equation*}
        t\langle c, v\rangle = \langle \nabla\phi(\hat{\mu}_t) - \nabla\phi(\mu_0), v\rangle \quad \text{for all } v\in TP. 
    \end{equation*} 
    On the other hand, for the gradient flow, we can use~\eqref{eq:explicitFRGF} and compute for $v\in TP$ 
    \begin{align*}
        \langle \nabla\phi(\mu_t) - \nabla\phi(\mu_0), v \rangle & = \int_{0}^t \partial_s \langle \nabla \phi(\mu_s), v \rangle \D s 
        = \int_{0}^t \langle \nabla^2 \phi(\mu_s)\partial_s \mu_s, v \rangle \D s 
        \\ & = \int_{0}^t \langle \nabla f(\mu_s) \mu_s, v \rangle \D s 
        = \int_{0}^t \langle c, v \rangle \D s = t \langle c, v \rangle . 
    \end{align*}
    This shows $\mu_t = \hat{\mu}_t$ as claimed. 
\end{proof}

