\begin{corollary}[Sublinear convergence rate,\cite{alvarez2004hessian}]\label{prop:sublinearRate}
    Consider Setting~\ref{setting:generalLP} and assume that the linear program~\eqref{eq:LP} admits a solution $\mu^\star\in P$. 
    Then for $\mu\in P$ it holds that 
\begin{equation}\label{eq:sublinearConvergence}
        c^\top \mu^\star - c^\top\mu_t \le \frac{\KL (\mu^\star, \mu) - \KL (\mu_t, \mu)}t \le \frac{\KL (\mu^\star, \mu_0)}t \quad \text{for all } t\in[0, T). 
    \end{equation}
\end{corollary}

\begin{proof}
    We have $c^\top \mu_t - t^{-1} \KL (\mu_t, \mu) \ge c^\top \mu^\star - t^{-1} \KL (\mu^\star, \mu)$ by the central path property.
    Rearranging yields the result. 
\end{proof}

\begin{proof}
    The local existence and uniqueness follow from the Picard-Lindelöf theorem~\cite{teschl2024ordinary}. Hence, it suffices to show that the Fisher-Rao gradient flow does not hit the boundary $\partial P$ in finite time. 
    By the central path property, this is equivalent to the statement that the solutions of all KL-regularized problems~\eqref{eq:centralPath} lie in the interior $\operatorname{int}(P)$ of the polyhedron, which can be easily checked. 
\end{proof}

