u)(\mu-
u) = \sum_{x\in \X} \mu_x \log  rac{\mu_x}{
u_x} - \sum_{x\in \X} \mu_x + \sum_{x\in \X} 
u_x 
\end{equation}
for $\mu, 
u\in\R_{\ge0}^\X$ with $\mu\ll
u$, where we use the common convention $0\log rac00\coloneqq0$.

By examining the definition of the Fisher-Rao metric we see that this is equivalent to 
\begin{equation}
\label{eq:characterizationFRGradient}
    \langle \nabla^2\phi(\mu)\nabla^{\FR}_P  f(\mu), v \rangle = \langle \nabla f(\mu), v \rangle \quad \text{for all } v\in TP. 
\end{equation}


We say that $(\mu_t)_{t\in [0, T)} \subseteq \operatorname{int}(P)$ solves the \emph{Fisher-Rao gradient flow} if it solves the gradient flow with respect to the Fisher-Rao metric, i.e., if 
\begin{equation}\label{eq:FRGF}
    \partial_t \mu_t = \nabla^{\FR}_P  f(\mu_t) \quad \text{for all } t\in[0, T). 
\end{equation}

By using the characterization~\eqref{eq:characterizationFRGradient} of $\nabla^{\FR}_P f(\mu_t)$, we see that $(\mu_t)_{t\in [0, T)} \subseteq \operatorname{int}(P)$ solves the Fisher-Rao gradient flow~\eqref{eq:FRGF}
if and only if we have 
\begin{equation}\label{eq:explicitFRGF}
    \langle \nabla^2 \phi(\mu_t) \partial_t \mu_t, v \rangle = \langle \nabla f(\mu_t), v \rangle 
    \quad \text{for all } v\in TP, t\in[0, T). 
\end{equation}

