        \max c^\top \mu \quad \text{subject to } \mu\in P, 
    \end{equation}
with cost $c\in\R^{\X}$ and feasible region $P = \Delta_\X \cap  \mathcal L$ with $P \cap \R^\X_{>0}\ne\emptyset$, where $\mathcal L\subseteq\R^{\X}$ is an affine space. 
By $(\mu_t)_{t\ge0}\subseteq\operatorname{int}(P)$ we denote the solution of the Fisher-Rao gradient flow~\eqref{eq:FRGF} with initial condition $\mu_0\in P \cap \R_{>0}^\X$ and the potential $f(\mu) = c^\top \mu$. 
\end{setting}

\begin{restatable}[Linear convergence of Fisher-Rao GFs of LPs]{theorem}{convergenceFRGF}
\label{thm:convergenceFRGF}
Consider Setting~\ref{setting:LP-inside-Simplex} and assume that the linear program~\eqref{eq:LP-inside-simplex} admits a unique solution $\mu^\star\in P$. 
Let 
\begin{align}\label{eq:Delta}
    \Delta \coloneqq \min \left\{ \frac{c^\top \mu^\star - 
    c^\top \mu}{\lVert \mu^\star - \mu \rVert_{\TV }} : \mu\in N(\mu^\star)  \right\},
\end{align}
where $N(\mu^\star)$ denotes the set of neighboring vertices of $\mu^\star$ and set 
\begin{equation}\label{eq:definitiont_0}
    t_0 \coloneqq \frac{2 \KL (\mu^\star, \mu_0)}{\Delta \cdot \min\{ \mu^\star_x : \mu^\star_x>0 \}} . 
\end{equation}
Then for any $t\ge t_0$ we have 
\begin{align}\label{eq:linearConvergenceKL}
    \KL (\mu^\star, \mu_t) \le \KL (\mu^\star, \mu_0) \exp\left( -\Delta(t-t_0) +  2 t_0 \Delta 
    \log\left(\frac{t+t_0}{2t_0}\right) \right), 
\end{align}
as well as 
\begin{align}\label{eq:linearConvergenceValue}
    c^\top \mu^\star - c^\top \mu_t \le \Delta \KL (\mu^\star, \mu_0) \exp\left( -\Delta(t-t_0) +  2 t_0 \Delta \log\left(\frac{t+t_0}{2t_0}\right) \right). 
\end{align}
\end{restatable}

\begin{proposition}[Central path property,\cite{alvarez2004hessian}]
    Consider Setting~\ref{setting:generalLP}. 
    Then $\mu_t$ is uniquely characterized by 
    \begin{equation}\label{eq:centralPath}
        \mu_t = \argmax\left\{ c^\top \mu - t^{-1} \KL (\mu, \mu_0) : \mu \in P \right\} \quad \text{for all } t\in(0,T). 
    \end{equation}
\end{proposition}

\begin{proof}
    Let $\hat{\mu}_t\in P$ denote the unique maximizer of $g(\mu)\coloneqq c^\top\mu - t^{-1} \KL (\mu, \mu_0)$ over $P$ for $t>0$, then surely $\hat{\mu}_t\in \operatorname{int}(P)$. 
    Thus, $\hat{\mu}_t$ is uniquely determined by $\langle \nabla g(\hat{\mu}_t), v\rangle = 0$ for all $v\in TP$. 
    Direct computation yields $\nabla g({\mu}) = c - t^{-1} (\nabla\phi(\mu) - \nabla\phi(\mu_0))$ and hence $\hat{\mu}_t$ is uniquely determined by 
    \begin{equation*}
        t\langle c, v\rangle = \langle \nabla\phi(\hat{\mu}_t) - \nabla\phi(\mu_0), v\rangle \quad \text{for all } v\in TP. 
    \end{equation*} 
    On the other hand, for the gradient flow, we can use~\eqref{eq:explicitFRGF} and compute for $v\in TP$ 
    \begin{align*}
        \langle \nabla\phi(\mu_t) - \nabla\phi(\mu_0), v \rangle & = \int_{0}^t \partial_s \langle \nabla \phi(\mu_s), v \rangle \D s 
        = \int_{0}^t \langle \nabla^2 \phi(\mu_s)\partial_s \mu_s, v \rangle \D s 
        \\ & = \int_{0}^t \langle \nabla f(\mu_s) \mu_s, v \rangle \D s 
        = \int_{0}^t \langle c, v \rangle \D s = t \langle c, v \rangle . 
    \end{align*}
    This shows $\mu_t = \hat{\mu}_t$ as claimed. 
\end{proof}

