\begin{lemma}[\cite{alvarez2004hessian}]\label{lem:evolutionKL}
Consider Setting~\ref{setting:generalLP}, whereby we allow $f\colon\R_{>0}^\X\to\R$ to be an arbitrary differentiable function, and fix $\mu\in P$. 
Then for any $t\ge0$, it holds that 
    \begin{equation}\label{eq:derivativeu}
        \partial_t \KL (\mu, \mu_t) = \langle \nabla f(\mu_t), \mu_t-\mu\rangle. 
    \end{equation}
\end{lemma}

\begin{proof}
    Denoting the negative Shannon entropy by $\phi$, we compute 
    \begin{align*}
        \partial_t \KL (\mu, \mu_t) = - \partial_t \phi(\mu_t) - \partial_t \langle \nabla \phi(\mu_t), \mu - \mu_t \rangle = \langle \nabla^2 \phi(\mu_t)\partial_t \mu_t, \mu_t - \mu \rangle.
    \end{align*}
    Now~\eqref{eq:explicitFRGF} yields the claim. 
\end{proof}

