\begin{restatable}{lemma}{TVLPEstimateWU}
\label{lem:TV-LP-estimate-withoutUniqueness}
Consider a polytope $P \subseteq \R^{\X}$ and denote by $F^\star$ the face of maximizers of the linear function $\mu\mapsto c^\top \mu$ over $P$. 
Denote the set of neighboring vertices of a vertex $\mu$ by $N(\mu)$ and let $\lVert \cdot\rVert\colon\R^{\X}\to\R_{\ge0}$ be an arbitrary semi-norm. 
Then either $F^\star = P$ or with $\frac{c}{0}\coloneqq+\infty$ for $c>0$, we have 
\begin{equation}
    \Delta\coloneqq \min \left\{ \frac{c^\top\mu^\star - c^\top\mu }{\lVert \mu^\star - \mu \rVert} : \mu^\star \in\operatorname{vert}(F^\star), \mu\in N(\mu^\star)\setminus F^\star \right\} > 0,
\end{equation}
and further 
\begin{equation}\label{eq:gapVSNorm-2}
     c^\top \mu^\star - c^\top \mu \ge \Delta \cdot \inf_{\mu^\star\in F^\star}  \lVert \mu^\star - \mu\rVert \quad \text{for all } \mu\in P.
\end{equation}
\end{restatable}

\begin{lemma}\label{lem:KLEstimateL1}
Consider a finite set $\X$ and a probability distribution $\mu\in \Delta_\X$. Let $c>1$ and set $\delta\coloneqq \frac{c-1}{c+1} 
    \cdot \min\{ \mu_x : \mu_x>0 \}>0$. 
Then for all $\nu\in\Delta_\X$ satisfying $\lVert \mu-\nu\rVert_\infty\le\delta$ it holds that 
\begin{equation}\label{eq:KLvsL1}
    \KL (\mu, \nu) \le c \cdot \lVert \mu - \nu \rVert_{\TV }. 
\end{equation}
\end{lemma}

