\begin{lemma}\label{app:lem:cone}
    Consider a polytope $P\subseteq\R^\X$, a face $F\subseteq P$ and consider the cone 
    \begin{align*}
        C\coloneqq \operatorname{cone}\Big\{ \nu-\mu : \mu\in\operatorname{vert}(F), \nu\in N(\mu)\setminus F \Big\}, 
    \end{align*}
    which is generated by the edges pointing out of $F$. 
    Then we have $P\subseteq F+C$. 
\end{lemma}

\begin{proof}
This is a generalization of~\cite[Lemma 3.6]{ziegler2012lectures}, which covers the case that $F$ consists of a single vertex. 
We will show that 
\begin{align*}
    F+C \supseteq\tilde P \coloneqq \bigcap \Big\{ H\subseteq \R^\X : H \text{ is a halfspace }, P\subseteq H, H\cap F\ne\emptyset \Big\} \supseteq P, 
\end{align*}
for which we pick an element $u\in \tilde P$. 
Consider a hyperplane $H = \{\mu:a^\top \mu = \alpha\}$ separating $F$ and $\operatorname{vert}(P)\setminus F$ and consider the \emph{face figure} $P/F\coloneqq P\cap H$, which is a polytope. 
Now, we consider a translation $\tilde H = \{ \mu : a^\top\mu= \beta \}$ of $H$,  such that $u\in \tilde H$. 
Now we have 
\begin{align*}
    \tilde P = \operatorname{conv}\left\{ \mu + \frac{a^\top \mu - \beta}{a^\top \mu - a^\top \nu} \cdot (\nu-\mu) : \mu\in\operatorname{vert}(F), \nu\in N(\mu)\setminus F \right\},
\end{align*}
see~\cite[Proposition 2.30]{zieglerdiscrete}. 
Hence, we can choose convex weights $\lambda_i$ such that 
\begin{align*}
    u = \sum_{i} \lambda_i (\mu_i + \alpha_i (\nu_i-\mu_i)) =  \sum_{i} \lambda_i \mu_i + \sum_{i} \alpha_i \lambda_i (\nu_i-\mu_i) \in F + C,
\end{align*}
where $\mu_i\in\operatorname{vert}(F), \nu_i \in N(\mu_i)\setminus F$.
\end{proof}

